const _CONCRETE_POOLS = [UNICODE_NOISE, MIME_NOISE, SERVICE_NOISE, PROTOCOL_NOISE, TIMEZONE_NOISE, INDEX_STATUS_NOISE, IANA_PORTS_NOISE, IANA_TLDS_NOISE, RFC_INDEX_NOISE, OURAIRPORTS_AIRPORTS_NOISE, OURAIRPORTS_FREQUENCIES_NOISE, OURAIRPORTS_RUNWAYS_NOISE, OURAIRPORTS_NAVAIDS_NOISE, GEONAMES_CITIES500_NOISE, NOAA_GHCND_STATIONS_NOISE, USGS_EARTHQUAKES_MONTH_NOISE];
export function pickMassiveNoisePair(rng) { const pool = _CONCRETE_POOLS[Math.floor(rng() * _CONCRETE_POOLS.length)] || UNICODE_NOISE; const row = pool[Math.floor(rng() * pool.length)] || ['NO SIGNAL','NO SIGNAL']; return Array.isArray(row) ? [String(row[0] ?? 'NO SIGNAL'), String(row[1] ?? row[0] ?? 'NO SIGNAL')] : [String(row), String(row)]; }
export function pickPoetryTag(rng) { const pool = rng() < 0.82 ? POETRY_SHORT_NOISE : POETRY_MEDIUM_NOISE; return String(pool[Math.floor(rng() * pool.length)] ?? 'NO SIGNAL'); }
